import json

import yaml

from prompty.model import ReplayMismatch


def test_load_json_replaymismatch():
    json_data = r"""
    {
      "index": 1,
      "message": "sample"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = ReplayMismatch.load(data)
    assert instance is not None
    assert instance.index == 1
    assert instance.message == "sample"


def test_load_yaml_replaymismatch():
    yaml_data = r"""
    index: 1
    message: sample

    """
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = ReplayMismatch.load(data)
    assert instance is not None
    assert instance.index == 1
    assert instance.message == "sample"


def test_roundtrip_json_replaymismatch():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "index": 1,
      "message": "sample"
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = ReplayMismatch.load(original_data)
    saved_data = instance.save()
    reloaded = ReplayMismatch.load(saved_data)
    assert reloaded is not None
    assert reloaded.index == 1
    assert reloaded.message == "sample"


